// HasAccount filters parents that have a matching Account using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Accounts).
func (w correctionPaymentWhereR[Q]) HasAccount(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Accounts.NameExpr()),
		sm.Where(Accounts.Columns.ID.EQ(w.cols.AccountID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// HasCorrection filters parents that have a matching Correction using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Corrections).
func (w correctionPaymentWhereR[Q]) HasCorrection(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Corrections.NameExpr()),
		sm.Where(Corrections.Columns.ID.EQ(w.cols.CorrectionID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

func (o *CorrectionPayment) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Account":
		rel, ok := retrieved.(*Account)
		if !ok {
			return fmt.Errorf("correctionPayment cannot load %T as %q", retrieved, name)
		}

		o.R.Account = rel
		o.R.Loaded.Account = true

		if rel != nil {
			rel.R.CorrectionPayments = CorrectionPaymentSlice{o}
		}
		return nil
	case "Correction":
		rel, ok := retrieved.(*Correction)
		if !ok {
			return fmt.Errorf("correctionPayment cannot load %T as %q", retrieved, name)
		}

		o.R.Correction = rel
		o.R.Loaded.Correction = true

		if rel != nil {
			rel.R.CorrectionPayments = CorrectionPaymentSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("correctionPayment has no relationship %q", name)
	}
}

type correctionPaymentPreloader struct {
	Account    func(...psql.PreloadOption) psql.Preloader
	Correction func(...psql.PreloadOption) psql.Preloader
}

func buildCorrectionPaymentPreloader() correctionPaymentPreloader {
	return correctionPaymentPreloader{
		Account: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Account, AccountSlice](psql.PreloadRel{
				Name: "Account",
				Sides: []psql.PreloadSide{
					{
						From:        CorrectionPayments,
						To:          Accounts,
						FromColumns: []string{"account_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Accounts.Columns.Names(), accountScanMapperNullable, opts...)
		},
		Correction: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Correction, CorrectionSlice](psql.PreloadRel{
				Name: "Correction",
				Sides: []psql.PreloadSide{
					{
						From:        CorrectionPayments,
						To:          Corrections,
						FromColumns: []string{"correction_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Corrections.Columns.Names(), correctionScanMapperNullable, opts...)
		},
	}
}

