// LoadAccount loads the correctionPayment's Account into the .R struct
func (o *CorrectionPayment) LoadAccount(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Account = nil
	o.R.Loaded.Account = false

	related, err := o.Account(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.CorrectionPayments = CorrectionPaymentSlice{o}

	o.R.Account = related
	o.R.Loaded.Account = true
	return nil
}

// LoadAccount loads the correctionPayment's Account into the .R struct
func (os CorrectionPaymentSlice) LoadAccount(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	accounts, err := os.Account(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Account = nil
		o.R.Loaded.Account = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	correctionPaymentByKey := make(map[uuid.UUID][]*CorrectionPayment, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		correctionPaymentByKey[o.AccountID] = append(correctionPaymentByKey[o.AccountID], o)
	}

	for _, rel := range accounts {

		owners, ok := correctionPaymentByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Account != nil {
				continue
			}

			rel.R.CorrectionPayments = append(rel.R.CorrectionPayments, o)

			o.R.Account = rel

		}
	}

	return nil
}

