type correctionPaymentJoins[Q dialect.Joinable] struct {
	typ        string
	Account    modAs[Q, accountColumns]
	Correction modAs[Q, correctionColumns]
}

func (j correctionPaymentJoins[Q]) aliasedAs(alias string) correctionPaymentJoins[Q] {
	return buildCorrectionPaymentJoins[Q](buildCorrectionPaymentColumns(alias), j.typ)
}

func buildCorrectionPaymentJoins[Q dialect.Joinable](cols correctionPaymentColumns, typ string) correctionPaymentJoins[Q] {
	return correctionPaymentJoins[Q]{
		typ: typ,
		Account: modAs[Q, accountColumns]{
			c: Accounts.Columns,
			f: func(to accountColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Accounts.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.AccountID),
					))
				}

				return mods
			},
		},
		Correction: modAs[Q, correctionColumns]{
			c: Corrections.Columns,
			f: func(to correctionColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Corrections.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.CorrectionID),
					))
				}

				return mods
			},
		},
	}
}
